import base64
from pathlib import Path
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'source'))

from torrc import TorrcError, build_torrc, read_bridge_file, transport_available

SNOWFLAKE = ROOT / 'packaging' / 'snowflake-bridges'
CERT = base64.b64encode(bytes(range(52))).decode().rstrip('=')
LINE = f'obfs4 192.0.2.10:443 0123456789ABCDEF0123456789ABCDEF01234567 cert={CERT} iat-mode=0'
BASE = [
    '# Generated by syslinuxos-anonimo. Do not edit: it is rewritten at every start.',
    'DataDirectory /var/lib/syslinuxos-anonimo/tor',
    'ControlSocket /run/syslinuxos-anonimo/tor/control',
    'CookieAuthentication 1',
    'CookieAuthFile /run/syslinuxos-anonimo/tor/control.authcookie',
    'SocksPort 0',
    'TransPort 127.0.0.1:9040',
    'DNSPort 127.0.0.1:9053',
    'AutomapHostsOnResolve 1',
    'AutomapHostsSuffixes .onion',
    'VirtualAddrNetworkIPv4 127.192.0.0/10',
    'Log notice syslog',
]
ALWAYS = lambda path: True


class TorrcTests(unittest.TestCase):
    def test_without_bridges(self):
        self.assertEqual(build_torrc('none').splitlines(), BASE)

    def test_obfs4(self):
        text = build_torrc('obfs4', [LINE], exists=ALWAYS)
        self.assertEqual(text.splitlines()[len(BASE):], [
            'UseBridges 1', 'ClientTransportPlugin obfs4 exec /usr/bin/obfs4proxy', 'Bridge ' + LINE])

    def test_shipped_snowflake_lines(self):
        lines = read_bridge_file(SNOWFLAKE)
        self.assertEqual(len(lines), 2)
        for line in lines:
            self.assertTrue(line.startswith('snowflake 192.0.2.'))
            self.assertIn(' front=app.datapacket.com ', line)
            self.assertNotIn('fronts=', line)
            self.assertIn('utls-imitate=hellorandomizedalpn', line)
        text = build_torrc('snowflake', snowflake_lines=lines, exists=ALWAYS)
        self.assertIn('ClientTransportPlugin snowflake exec /usr/bin/snowflake-client', text)
        self.assertEqual(text.count('\nBridge snowflake '), 2)

    def test_missing_program(self):
        with self.assertRaisesRegex(TorrcError, '^The obfs4 bridge program is not installed$'):
            build_torrc('obfs4', [LINE], exists=lambda path: False)
        with self.assertRaisesRegex(TorrcError, '^The snowflake bridge program is not installed$'):
            build_torrc('snowflake', snowflake_lines=read_bridge_file(SNOWFLAKE), exists=lambda path: False)

    def test_no_lines_or_wrong_type(self):
        with self.assertRaisesRegex(TorrcError, '^No obfs4 bridge lines available$'):
            build_torrc('obfs4', [], exists=ALWAYS)
        with self.assertRaisesRegex(TorrcError, '^No snowflake bridge lines available$'):
            build_torrc('snowflake', snowflake_lines=[LINE], exists=ALWAYS)

    def test_unknown_type(self):
        with self.assertRaisesRegex(TorrcError, '^Unknown bridge type$'):
            build_torrc('meek')

    def test_transport_available(self):
        self.assertTrue(transport_available('none', exists=lambda path: False))
        self.assertTrue(transport_available('obfs4', exists=lambda path: path == '/usr/bin/obfs4proxy'))
        self.assertFalse(transport_available('snowflake', exists=lambda path: False))
        self.assertFalse(transport_available('meek', exists=ALWAYS))

    def test_read_bridge_file_missing(self):
        with tempfile.TemporaryDirectory() as tmp:
            self.assertEqual(read_bridge_file(Path(tmp) / 'missing'), [])


if __name__ == '__main__':
    unittest.main()
